// Logic of the printable version of the public guides (/help/print, HelpPrint.svelte), kept out
// of the components so that it is unit tested in Node. The page is printed (or saved as PDF) by
// the browser, never generated by the server (threat model P29); it is dated and carries the
// application version, since a printed copy outlives the rules it describes (T-234).
import { PUBLIC_GUIDES, type HelpLinks } from './help';
import type { HelpGuide, HelpGuideSet } from './types';

/** Shown in place of the application version when GET /version fails. */
export const UNKNOWN_VERSION = '—';

/** Guides of the printable version, depositor first then recipient (PUBLIC_GUIDES order). */
export function printGuides(set: HelpGuideSet): HelpGuide[] {
  const out: HelpGuide[] = [];
  for (const id of PUBLIC_GUIDES) {
    const guide = set.guides.find((g) => g.id === id);
    if (guide !== undefined) out.push(guide);
  }
  return out;
}

/** Version of the running instance (GET /version), UNKNOWN_VERSION when it cannot be read. */
export async function loadVersion(get: () => Promise<{ version: string }>): Promise<string> {
  try {
    const { version } = await get();
    return version.trim() === '' ? UNKNOWN_VERSION : version;
  } catch {
    return UNKNOWN_VERSION;
  }
}

/** Opens the print dialog of the browser (print, or save as PDF). */
export function printPage(target: Pick<Window, 'print'>): void {
  target.print();
}

/**
 * Links of the printable guides: rendered as plain text (a link means nothing on paper, and the
 * section ids of two guides on one page could collide).
 */
export const PLAIN_LINKS: HelpLinks = {
  plain: true,
  topicHref: () => '',
  link: () => ({ destroy: () => undefined }),
  onanchor: () => undefined,
};
